  pct_surviving: number;      // 0..100
  pct_ever_na: number;
  pct_ever_default: number;
  pct_ever_default_hc: number | null;
  pct_ever_default_1l: number | null;
  pct_ever_modified: number | null;
  pct_ever_modified_hc: number | null;
  pct_ever_b80: number | null;
  pct_b90_alive: number;
  pct_na_unknown: number;     // % of eligible cost left out: latest NA status unknown
  pct_na_history_gap: number; // % counted as clear but with an earlier unknown quarter
  na_partial: boolean;
  hc_cost_share: number;      // % of counted cost with a HIGH or MED date
  pct_mod_unknown: number;    // % of eligible cost whose modification history is unknown
  mod_partial: boolean;       // pct_mod_unknown >= 5
